def min_operations(n, k, a, b):
    if k == 0:
        return -1

    b_set = set(b)
    operations = 0
    last_valid_index = -1

    for i in range(n):
        if i + 1 in b_set:
            continue

        if i == 0 or a[i] > a[last_valid_index]:
            last_valid_index = i
        else:
            operations += 1
            while last_valid_index >= 0 and a[last_valid_index] >= a[i]:
                last_valid_index -= 1
            if last_valid_index == -1:
                return -1
            last_valid_index += 1

    return operations

