        return sum(1 for i in range(1, n) if a[i] <= a[i - 1])

    b_set = set(b)
    changes = 0

    for i in range(1, n):
        if a[i] <= a[i - 1]:
            if i + 1 in b_set:
                return -1
            j = i + 1
            while j < n and j in b_set:
                j += 1
            if j >= n:
                return -1
            a[i] = a[j]
            changes += 1

    return changes

